(require $root.'/database/migrations/2026_10_30_010000_add_trip_navigation.php')->up();
(require $root.'/database/migrations/2026_10_30_010000_add_trip_navigation.php')->up();cpCheck(TripNavigation::ready(),'navigation migration is idempotent and ready');
config(['navigation.osrm_enabled'=>true,'navigation.osrm_url'=>'https://router.project-osrm.org','services.google_maps.api_key'=>'']);
$driver=$person('Demo journey driver','driver');$vehicle=$car($driver,'JOURNEY-DEMO');
$pA=$newRequest('Demo hostel passenger',2.3125,102.316);$pB=$newRequest('Demo library passenger',2.315,102.319);
$options=['pool_seat_capacity'=>3,'pool_origin_latitude'=>2.311,'pool_origin_longitude'=>102.314];
$ride=OnDemandRides::accept($driver->user_id,$pB->request_id,$vehicle->vehicle_id,$options);OnDemandRides::accept($driver->user_id,$pA->request_id,$vehicle->vehicle_id);
$id=$ride->ride_id;$nav=new TripNavigationController;$dc=new DriverController;
$call=function($user,$data=[],$method='POST',$path='/synthetic'){
    Auth::forgetGuards();Auth::guard()->setUser($user);$r=Request::create('http://localhost'.$path,$method,$data,[],[],['HTTP_ACCEPT'=>'application/json']);$r->setUserResolver(fn()=>$user);$r->setLaravelSession(app('session')->driver());app()->instance('request',$r);return $r;
};
$testPath=[['lat'=>2.311,'lng'=>102.314],['lat'=>2.312,'lng'=>102.315],['lat'=>2.3125,'lng'=>102.316],['lat'=>2.314,'lng'=>102.318],['lat'=>2.315,'lng'=>102.319],['lat'=>2.3139,'lng'=>102.3183]];
