if(in_array('--navigation-preview',$argv,true)&&is_file($root.'/tests/fixtures/utem-navigation-road.json'))$roadFixture=json_decode(file_get_contents($root.'/tests/fixtures/utem-navigation-road.json'),true);
Http::fake(['router.project-osrm.org/*'=>Http::response($roadFixture,200)]);
$before=TripNavigation::status($ride->fresh(),$driver);cpCheck($before['status']==='scheduled'&&$before['location']===null,'planned rides show no live GPS before starting');
cpCheck(str_ends_with($nav->show($call($driver,[],'GET'),$id)->getTargetUrl(),'/driver/schedule'),'a scheduled trip cannot open the live map');
cpCheck(OnDemandRides::payload($pA->fresh()->load('ride'))['navigationUrl']===null,'waiting bookings do not expose a tracking link');
cpReject(fn()=>$nav->advance($call($driver,['stop_key'=>$before['next']['key']]),$id),409,'stops cannot be confirmed before trip start');
$started=$dc->handleAction($call($driver,['action'=>'update_status','ride_id'=>$id,'next_status'=>'in_progress']));
cpCheck(str_ends_with($started->getTargetUrl(),'/trips/'.$id.'/map')&&$ride->fresh()->navigation_plan!==null,'Start pickups redirects to the journey map and freezes the stop order');
$snapshot=$ride->fresh()->navigation_plan;
cpCheck($snapshot[1]['label']==='Pickup: Demo hostel passenger pickup','map starts with the passenger nearest the driver rather than acceptance order');
$page=$nav->show($call($driver,[],'GET'),$id);$html=$page->getContent();
cpCheck(str_contains($html,'journeyNavigationMap')&&str_contains($html,'Passenger on board')===false&&str_contains($html,'navigationConfirm'),'driver receives the road map and stop confirmation controls');
$road=NavigationRoad::route(TripNavigation::status($ride->fresh(),$driver)['stops']);
cpCheck($road['road']&&$road['source']==='osrm'&&count($road['path'])>2,'road provider supplies geometry through the ordered stops');
Http::assertSent(fn($r)=>str_contains($r->url(),'/route/v1/driving/102.314,2.311;102.316,2.3125;102.319,2.315;102.3183,2.3139'));
cpReject(fn()=>$nav->show($call($driver,['demo'=>1],'GET'),$id),404,'retired demo query URLs cannot open a simulation');
cpCheck(!str_contains($html,'navigationReplay')&&!str_contains($html,'Run pickup')&&!str_contains($html,'DEMO ANIMATION'),'active map contains only live navigation controls');
cpCheck(OnDemandRides::payload($pA->fresh()->load('ride'))['navigationUrl']!==null,'active passengers receive the live tracking link');
cpCheck(str_ends_with((new App\Http\Controllers\TrackingController)->index()->getTargetUrl(),'/trips/'.$id.'/map'),'the legacy tracking entry opens the current live trip instead of a preview');
cpReject(fn()=>$nav->status($call($d3),$id),404,'another driver cannot read this journey');
cpReject(fn()=>$nav->status($call($admin),$id),403,'admin location access stays in the separate admin feed');
cpReject(fn()=>$nav->status($call($late->passenger),$id),404,'unconfirmed passengers cannot read the journey GPS');
$passenger=$pA->passenger;$passengerState=$nav->status($call($passenger),$id)->getData(true)['navigation'];
cpCheck(!str_contains(json_encode($passengerState),'Demo library passenger')&&!collect($passengerState['stops'])->contains('lat',2.315),'confirmed passengers see own pickup and drop-off without strangers names or pins');
cpReject(fn()=>$nav->advance($call($passenger,['stop_key'=>$before['next']['key']]),$id),403,'passengers cannot mark pickups or drop-offs');
DriverLocation::save($id,['latitude'=>2.3112,'longitude'=>102.3142,'accuracy'=>8,'capturedAt'=>now()->timestamp,'token'=>'never-expose-this-token','sharing'=>true,'gpsState'=>'live']);
$live=$nav->status($call($passenger),$id)->getData(true);
cpCheck($live['navigation']['gps']==='live'&&$live['navigation']['location']['lat']===2.3112&&!str_contains(json_encode($live),'never-expose-this-token'),'confirmed passengers receive genuine GPS without the upload token');
cpCheck(str_contains($nav->status($call($passenger),$id)->headers->get('Cache-Control'),'no-store'),'participant location responses forbid browser caching');
DriverLocation::save($id,['latitude'=>2.3112,'longitude'=>102.3142,'accuracy'=>8,'capturedAt'=>now()->subSeconds(31)->timestamp,'sharing'=>true,'gpsState'=>'live']);
cpCheck($nav->status($call($passenger),$id)->getData(true)['navigation']['gps']==='stale','old GPS remains explicitly stale rather than simulated live movement');
$driverState=TripNavigation::status($ride->fresh(),$driver);$first=$driverState['next']['key'];$drop=collect($driverState['stops'])->firstWhere('kind','dropoff')['key'];
cpReject(fn()=>$nav->advance($call($driver,['stop_key'=>$drop]),$id),422,'drop-off cannot skip passengers still waiting for pickup');
$firstResponse=$nav->advance($call($driver,['stop_key'=>$first]),$id)->getData(true)['navigation'];
cpCheck($firstResponse['next']['key']!==$first&&RideBooking::where('ride_id',$id)->whereNotNull('picked_up_at')->count()===1,'confirming pickup moves to the next passenger once');
$nav->advance($call($driver,['stop_key'=>$first]),$id);
cpCheck(RideBooking::where('ride_id',$id)->whereNotNull('picked_up_at')->count()===1,'a retried pickup confirmation never collects a second passenger');
cpCheck($nav->status($call($passenger),$id)->getData(true)['navigation']['onBoard'],'the collected passenger sees their on-board status');
$nav->advance($call($driver,['stop_key'=>$firstResponse['next']['key']]),$id);
cpCheck(TripNavigation::status($ride->fresh(),$driver)['next']['kind']==='dropoff','after both pickups the common drop-off becomes the next stop');
$nav->advance($call($driver,['stop_key'=>$drop]),$id);
cpCheck(TripNavigation::status($ride->fresh(),$driver)['allDroppedOff']&&RideBooking::where('ride_id',$id)->whereNotNull('dropped_off_at')->count()===2,'common drop-off records both passengers exactly once');
$dc->handleAction($call($driver,['action'=>'update_status','ride_id'=>$id,'next_status'=>'completed']));
$ended=$nav->status($call($passenger),$id)->getData(true);
cpCheck($ended['ended']===true&&!isset($ended['navigation'])&&DriverLocation::get($id)===null,'completed trips return an end signal without GPS or route stops');
cpCheck(str_ends_with($ended['redirectUrl'],'/passenger/bookings')&&str_ends_with($nav->show($call($passenger,[],'GET'),$id)->getTargetUrl(),'/passenger/bookings'),'an already-open or bookmarked completed map returns passengers to their bookings');
cpCheck(str_ends_with($nav->show($call($driver,[],'GET'),$id)->getTargetUrl(),'/driver/schedule'),'completed map URLs return the driver to the schedule');
cpCheck(OnDemandRides::payload($pA->fresh()->load('ride'))['navigationUrl']===null,'completed requests no longer contain a tracking link');
cpCheck(str_ends_with((new App\Http\Controllers\TrackingController)->index()->getTargetUrl(),'/driver/schedule'),'legacy tracking without an active trip returns to the driver schedule');
cpCheck(DB::table('ride_carbon_reports')->where('ride_id',$id)->count()===1,'navigation completion preserves one shared carbon report');
cpReject(fn()=>$nav->advance($call($driver,['stop_key'=>$drop]),$id),409,'ended trips cannot receive new stop events');
Auth::forgetGuards();Auth::guard()->setUser($driver);$csrf=Request::create('http://localhost/trips/'.$id.'/stops','POST',['stop_key'=>$first],[],[],['HTTP_ACCEPT'=>'application/json']);
cpCheck($kernel->handle($csrf)->getStatusCode()===419,'stop confirmation has CSRF protection');
config(['navigation.osrm_enabled'=>false]);Cache::flush();$fallback=NavigationRoad::route($snapshot);
cpCheck(!$fallback['road']&&$fallback['source']==='approximate','unavailable road routing produces a labelled approximate path');
if(in_array('--navigation-preview',$argv,true)){
    URL::forceRootUrl('http://localhost/workshop');config(['navigation.osrm_enabled'=>true]);Cache::flush();
    // A synthetic copy is active only in this memory database for the preview.
    $preview=$ride->fresh();$preview->ride_status='in_progress';$preview->save();$preview->bookings()->update(['picked_up_at'=>null,'dropped_off_at'=>null]);
    $folder=$root.'/public/device-review/trip-navigation';if(!is_dir($folder))mkdir($folder,0777,true);
    DriverLocation::save($id,['latitude'=>2.3112,'longitude'=>102.3142,'accuracy'=>8,'capturedAt'=>now()->timestamp,'sharing'=>true,'gpsState'=>'live']);
    $fixture=TripNavigation::status($preview->fresh(),$driver);file_put_contents($folder.'/feed.json',json_encode(['navigation'=>$fixture]));
    $html=$nav->show($call($driver,[],'GET'),$id)->getContent();
    $html=str_replace(json_encode(url('api/trips/'.$id.'/navigation')),json_encode(url('device-review/trip-navigation/feed.json')),$html);
    $html=preg_replace('~<details class="global-driver-gps">.*?</details>~s','',$html);
    $html=preg_replace('~<script src="[^"]*/js/driver-location\.js[^"]*" defer></script>~','',$html);
    $html=preg_replace('~<form\b~','<form inert',$html);
    $html=str_replace('<body class="app-page navigation-page">','<body class="app-page navigation-page"><div style="padding:8px;background:#e9f0df;text-align:center;font:11px system-ui">SYNTHETIC REVIEW · GPS fixture only. No real trip data or device GPS.</div>',$html);
    $html=str_replace('</head>','<meta name="robots" content="noindex,nofollow"><script>document.addEventListener("click",function(e){if(e.target.closest("#navigationConfirm")){e.preventDefault();e.stopImmediatePropagation();}},true);document.addEventListener("submit",function(e){e.preventDefault();e.stopImmediatePropagation();},true);</script></head>',$html);file_put_contents($folder.'/live.html',$html);
}
echo "Trip navigation: $checks total checks passed; SQLite memory and fake route provider only.\n";
